import Foundation

struct QuoteDatabase {
    static func quote(for tid: String, dayNumber: Int) -> Quote {
        let pool = quotes[tid] ?? []
        guard !pool.isEmpty else {
            return Quote(q: "Let food be thy medicine.", a: "Hippocrates", c: "Ancient Greek physician, father of medicine.")
        }
        let index = (dayNumber - 1) % pool.count
        return pool[index]
    }

    static let quotes: [String: [Quote]] = [
        "ayurveda": ayurvedaQuotes,
        "tcm": tcmQuotes,
        "persian": persianQuotes,
        "african": africanQuotes,
        "latin": latinQuotes,
        "euro": euroQuotes,
        "folk": folkQuotes
    ]

