    ]

    // MARK: - Traditional Chinese Medicine (21 quotes)
    static let tcmQuotes: [Quote] = [
        Quote(q: "The superior physician prevents disease. The mediocre physician treats disease before it is evident. The inferior physician treats disease after it is apparent.",
              a: "Huangdi Neijing",
              c: "The Yellow Emperor's Classic of Medicine (~200 BCE) is the foundational canonical text of Chinese medicine, establishing its philosophical, diagnostic, and therapeutic framework."),
        Quote(q: "Where Qi goes, blood follows. Where blood flows, life flourishes.",
              a: "TCM principle",
              c: "Qi (vital energy) and Xue (blood) are considered inseparable in TCM theory. Their harmonious circulation through the meridians is the primary indicator of good health."),
        Quote(q: "Nourish the root, and the branches will take care of themselves.",
              a: "Huangdi Neijing",
              c: "TCM treats underlying constitutional imbalances rather than isolated symptoms — the root (Ben) is always addressed before the branch (Biao) manifestation."),
        Quote(q: "The herbs of the mountain and the sea hold within them the memory of ten thousand cures.",
              a: "Li Shizhen, Bencao Gangmu",
              c: "Li Shizhen (1518–1593) catalogued nearly 1,900 medicinal substances in his Bencao Gangmu (Compendium of Materia Medica) — the most comprehensive herbal encyclopedia in history."),
        Quote(q: "When you treat illness, first treat the mind.",
              a: "Sun Simiao",
              c: "Sun Simiao (581–682 CE), known as China's 'King of Medicine,' emphasized psychological harmony as a prerequisite for physical healing in his Essential Prescriptions Worth a Thousand Gold."),
        Quote(q: "The five flavors nourish the five organs. Let your medicine be your food.",
              a: "Huangdi Neijing",
              c: "TCM dietary theory assigns sour, bitter, sweet, pungent, and salty flavors to the liver, heart, spleen, lung, and kidney — each flavor strengthening or draining the associated organ."),
        Quote(q: "Ginkgo has lived ten thousand years. Drink of its patience and longevity.",
              a: "TCM folk saying",
              c: "Ginkgo biloba — sometimes called a 'living fossil' — has existed for 270 million years and is one of the most researched medicinal plants in TCM for brain circulation and longevity."),
        Quote(q: "The sage does not treat illness after it arises, but prevents it before it begins.",
              a: "Laozi, Tao Te Ching",
              c: "Laozi's philosophy of non-action (wu-wei) and working with natural flow profoundly shaped Chinese medicine's emphasis on prevention, seasonal living, and gentle intervention."),
        Quote(q: "Yin and Yang are not opposites — they are the dance of one reality.",
              a: "TCM principle",
              c: "The Yin-Yang theory at the core of TCM teaches that apparent opposites are complementary aspects of a unified whole — a framework applied to every physiological and pathological process."),
        Quote(q: "The kidney is the root of life, the reservoir of ancestral Jing.",
              a: "TCM teaching",
              c: "Jing — often translated as 'essence' — is the deepest form of vital energy in TCM, stored in the kidneys and governing growth, reproduction, and the lifespan itself."),
        Quote(q: "Calm the Shen, and the ten thousand anxieties dissolve of themselves.",
              a: "Sun Simiao",
              c: "Shen in TCM refers to the mind-spirit that resides in the heart. Herbs that calm the Shen — like Goji, Longan, and Suan Zao Ren — are central to mental and emotional health treatment."),
        Quote(q: "The bitter herb teaches discipline. The sweet herb teaches comfort. Both are necessary.",
              a: "Li Shizhen",
              c: "Li Shizhen's Bencao Gangmu organized all medicinal substances by flavor, temperature, and affinity for specific organ meridians — a classification system still used today."),
        Quote(q: "Water flowing gently shapes stone. Healing that is gradual is healing that endures.",
              a: "TCM proverb",
              c: "Chronic conditions in TCM are typically treated over months and seasons, in alignment with the understanding that deeply rooted imbalances require consistent, gentle correction."),
        Quote(q: "He who knows the Dao needs no medicine. He who follows the Dao needs little.",
              a: "Laozi",
              c: "The Daoist concept of living in accordance with the natural way — through rest, moderate eating, seasonal adaptation — was considered the highest form of preventive medicine."),
        Quote(q: "Spring is liver season. Autumn is lung season. Let the body follow the year.",
              a: "Huangdi Neijing",
              c: "TCM's five-phase theory maps each season to an organ system, guiding dietary choices, emotional work, and herbal support throughout the annual cycle."),
        Quote(q: "The tongue never lies. It shows the condition of every organ within.",
              a: "TCM diagnostic teaching",
              c: "Tongue diagnosis — examining color, coating, shape, and moisture — is one of TCM's most sophisticated diagnostic tools, revealing the state of internal organs without invasive testing."),
        Quote(q: "Each plant has a story. Learn the story, and you will know the medicine.",
              a: "Li Shizhen",
              c: "Li Shizhen traveled extensively to collect botanical specimens and folk healing knowledge, interviewing farmers and herbalists across China to compile the Bencao Gangmu."),
        Quote(q: "Where there is free flow, there is no pain. Where there is pain, there is no free flow.",
              a: "TCM clinical principle",
              c: "This principle from classical TCM explains pain and disease as stagnation — of Qi, blood, phlegm, or dampness — and guides treatment toward restoring circulation and flow."),
        Quote(q: "To nourish life is the great art. Nothing else comes before it.",
              a: "Sun Simiao",
              c: "Sun Simiao's Essential Prescriptions placed yangsheng — the art of nourishing life through herbs, food, movement, and meditation — as the pinnacle of medical practice."),
        Quote(q: "Goji berries carry the red of the sun and the sweetness of the earth. They restore what time takes away.",
              a: "TCM folk tradition",
              c: "Gou Qi Zi (Goji berries) are classified in TCM as a Liver and Kidney tonic, traditionally consumed daily to support vision, vitality, and graceful aging."),
        Quote(q: "The body remembers what the mind forgets. Trust its wisdom.",
              a: "TCM teaching",
              c: "In TCM, the body's responses — cravings, pain, temperature sensitivity — are considered meaningful signals from the organ systems, to be read rather than suppressed.")
    ]

    // MARK: - Persian Medicine (21 quotes)
